function reportRestoreResult(result, pullableSource, options) {
  if (!result.success) {
    console.error(`\u274C Failed to restore from backup: ${result.error}`);
    return result.primitivesUnresolved.length;
  }
  if (result.filesWritten > 0) {
    writeSuccess(`\u2705 Restored ${result.filesWritten} file(s) from backup (${result.filesUnchanged} unchanged)`);
  } else {
    writeInfo(`\u2139\uFE0F  Backup matched local disk \u2014 0 files written${options.verbose ? ` (${result.filesUnchanged} already up-to-date)` : ""}`);
  }
  if (result.primitivesUnresolved.length === 0) return 0;
  console.log();
  writeInfo(options.verbose ? "\u26A0\uFE0F  The following primitives drifted but are NOT in the backup:" : "\u26A0\uFE0F  Primitives not in backup (source unavailable):");
  for (const name of result.primitivesUnresolved) {
    const item = pullableSource.find((i) => i.name === name);
    const label = item ? `${item.type}/${name}` : name;
    writeInfo(`   - ${label}`);
  }
  if (options.verbose) {
    writeInfo("   The backup does not contain source for these primitives.");
    writeInfo("   Ask whoever made the changes to run `lua push all --force`,");
    writeInfo("   or run `lua <primitive> delete <name>` to remove them from the server.");
    if (result.backupAgeDays !== null && result.backupAgeDays >= 1) {
      writeInfo(`   (Backup is ${result.backupAgeDays} day(s) old \u2014 may be stale.)`);
    }
  }
  return result.primitivesUnresolved.length;
}
