async function handlePrimitiveDriftInteractive(context, primitiveDrift) {
  showPrimitiveDrift(primitiveDrift.items, primitiveDrift.backupAvailable);
  let hasRestoredFromBackup = false;
  let hasSyncedMcp = false;
  for (const item of primitiveDrift.items) {
    const choices = [];
    const isMcp = item.type === "mcpServer";
    if (item.status !== "missing-locally") {
      choices.push({
        name: "\u{1F4E4} Push local to server",
        value: "push"
      });
    }
    if (item.status !== "missing-on-server") {
      if (isMcp) {
        choices.push({
          name: "\u{1F4E5} Pull from server",
          value: "pull-mcp"
        });
      } else if (primitiveDrift.backupAvailable) {
        choices.push({
          name: "\u{1F4E5} Pull from backup",
          value: "pull"
        });
      } else {
        choices.push({
          name: "\u{1F4E5} Pull from backup (unavailable)",
          value: "pull-unavailable"
        });
      }
    }
    choices.push({
      name: "\u23ED\uFE0F  Skip",
      value: "skip"
    });
    const answer = await safePrompt([
      {
        type: "list",
        name: "action",
        message: `${item.type}: ${item.name} \u2014 What would you like to do?`,
        choices
      }
    ]);
    if (!answer || answer.action === "skip") {
      writeInfo(`Skipped ${item.type}: ${item.name}`);
      continue;
    }
    if (answer.action === "push") {
      const pushArg = item.type === "mcpServer" ? "mcp" : item.type;
      writeInfo(`\u{1F4A1} To push this ${item.type}, run: lua push ${pushArg} --name "${item.name}"`);
    } else if (answer.action === "pull-mcp") {
      if (hasSyncedMcp) {
        writeInfo(`\u2705 Already synced MCP servers (includes ${item.name})`);
      } else {
        writeProgress("\u{1F4E5} Syncing MCP servers from server...");
        try {
          const yamlConfig = readYamlConfig();
          const result = await mcpServerHandler.syncWithServer(context.apiKey, context.agentId, yamlConfig);
          writeSuccess(result.yamlUpdated ? "\u2705 MCP servers synced from server" : "\u2705 MCP servers already in sync");
          hasSyncedMcp = true;
        } catch (error) {
          console.error(`\u274C Failed to sync MCP servers: ${error.message}`);
        }
      }
    } else if (answer.action === "pull") {
      if (hasRestoredFromBackup) {
        writeInfo(`\u2705 Already restored from backup (includes ${item.name})`);
      } else {
        const pullableSource = primitiveDrift.items.filter((i) => i.type !== "mcpServer" && i.status !== "missing-on-server");
        writeProgress("\u{1F4E5} Restoring project files from backup...");
        const result = await restoreFromBackupForSync(context.apiKey, context.agentId, pullableSource.map((i) => i.name));
        if (result.success) {
          hasRestoredFromBackup = true;
          reportRestoreResult(result, pullableSource, {
            verbose: false
          });
        } else {
          console.error(`\u274C Failed to restore from backup: ${result.error}`);
        }
      }
    } else if (answer.action === "pull-unavailable") {
      writeInfo('\u26A0\uFE0F  No backup available. Run "lua push backup" first to enable pulling from server.');
    }
  }
}
