async function runIncludeSourceHook(apiKey, agentId, selectedType) {
  const stats = {
    attempted: 0,
    attached: 0,
    failed: 0
  };
  try {
    const archive = encodeWorkspaceArchive(process.cwd());
    if (!archive) {
      writeInfo("\u{1F4A1} --include-source: workspace has no archivable source, skipping");
      return stats;
    }
    const config = readYamlConfig();
    const skills = config?.skills ?? [];
    if (skills.length === 0) {
      if (selectedType !== "skill") {
        writeInfo(`\u{1F4A1} --include-source: no skills in lua.skill.yaml to attach source to (selectedType=${selectedType})`);
      } else {
        writeInfo("\u{1F4A1} --include-source: no skills in lua.skill.yaml");
      }
      return stats;
    }
    stats.attempted = skills.length;
    const skillApi = new SkillApi(BASE_URLS.API, apiKey, agentId);
    const concurrency = 5;
    for (let i = 0; i < skills.length; i += concurrency) {
      const batch = skills.slice(i, i + concurrency);
      await Promise.all(batch.map(async (skill) => {
        try {
          const response = await skillApi.attachSkillSource(skill.skillId, skill.version, {
            sourceArchive: archive,
            archiveSchemaVersion: ARCHIVE_SCHEMA_VERSION,
            tools: []
          });
          if (response.success) {
            stats.attached++;
          } else {
            stats.failed++;
            writeInfo(`   \u21B3 attach failed for ${skill.name}@${skill.version}: ${response.error?.message ?? "unknown"}`);
          }
        } catch (err) {
          stats.failed++;
          writeInfo(`   \u21B3 attach failed for ${skill.name}@${skill.version}: ${err instanceof Error ? err.message : String(err)}`);
        }
      }));
    }
    if (stats.failed === 0) {
      writeInfo(`\u{1F4A1} Source attached to ${stats.attached}/${stats.attempted} skill(s) \u2014 Builder UI will reflect CLI edits`);
    } else {
      writeError(`--include-source: ${stats.failed}/${stats.attempted} skill source attach(es) failed (non-fatal \u2014 primitive is deployed, per-agent backup is current)`);
    }
  } catch (err) {
    writeError(`--include-source: hook setup failed (non-fatal \u2014 primitive is deployed, per-agent backup is current): ${err instanceof Error ? err.message : String(err)}`);
  }
  return stats;
}
