async function runPhoneInteractive(api, agentId, orgId, apiKey) {
  const { action } = await safePrompt([
    {
      type: "list",
      name: "action",
      message: "Phone numbers \u2014 what would you like to do?",
      choices: [
        {
          name: "Search available numbers",
          value: "search"
        },
        {
          name: "Purchase a number",
          value: "purchase"
        },
        {
          name: "Bind a number to this agent",
          value: "bind"
        },
        {
          name: "Unbind a number from this agent",
          value: "unbind"
        },
        {
          name: "List my numbers",
          value: "list"
        },
        {
          name: "Release a number",
          value: "release"
        }
      ]
    }
  ]);
  switch (action) {
    case "search":
      await doSearch(api);
      break;
    case "purchase":
      await doPurchase(api, agentId, orgId, apiKey);
      break;
    case "bind":
      await doBind(api, agentId, apiKey);
      break;
    case "unbind":
      await doUnbind(api, agentId);
      break;
    case "list":
      await doList(api, orgId);
      break;
    case "release":
      await doRelease(api, orgId);
      break;
  }
  trackEvent("cli_channels_phone_completed", {
    action
  });
}
