async function fetchEntitiesByType(apiKey, agentId, type) {
  switch (type) {
    case "skill": {
      const res = await new SkillApi(BASE_URLS.API, apiKey, agentId).getSkills();
      return res.data?.skills || [];
    }
    case "job": {
      const res = await new JobApi(BASE_URLS.API, apiKey, agentId).getJobs({
        includeDynamic: true
      });
      return res.data?.jobs || [];
    }
    case "webhook": {
      const res = await new WebhookApi(BASE_URLS.API, apiKey, agentId).getWebhooks();
      return res.data?.webhooks || [];
    }
    case "preprocessor": {
      const res = await new PreProcessorApi(BASE_URLS.API, apiKey, agentId).getPreProcessors();
      return res.data?.preprocessors || [];
    }
    case "postprocessor": {
      const res = await new PostProcessorApi(BASE_URLS.API, apiKey, agentId).getPostProcessors();
      return res.data?.postprocessors || [];
    }
    case "device": {
      const res = await new DeviceApi(BASE_URLS.API, apiKey, agentId).getDevices();
      return res.data?.devices || [];
    }
    default:
      return [];
  }
}
