async function subscribeCore(context, webhookId, webhookName, eventType) {
  if (!AVAILABLE_EVENT_TYPES.includes(eventType)) {
    console.error(`\u274C Invalid event type: "${eventType}"`);
    console.log("\nAvailable event types:");
    AVAILABLE_EVENT_TYPES.forEach((e) => console.log(`  \u2022 ${e}`));
    return false;
  }
  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const webhooksResponse = await webhookApi.getWebhooks();
  if (!webhooksResponse.success || !webhooksResponse.data?.webhooks) {
    console.error("\u274C Failed to fetch webhooks");
    return false;
  }
  const webhook = webhooksResponse.data.webhooks.find((w) => w.id === webhookId || w.name === webhookName);
  if (!webhook) {
    console.error(`\u274C Webhook "${webhookName}" not found on server`);
    return false;
  }
  const currentSubs = webhook.eventSubscriptions || [];
  if (currentSubs.includes(eventType)) {
    writeInfo(`\u2139\uFE0F  Webhook "${webhookName}" is already subscribed to ${eventType}`);
    return true;
  }
  writeProgress(`\u{1F504} Subscribing webhook "${webhookName}" to ${eventType}...`);
  const response = await webhookApi.updateWebhook(webhook.id, {
    eventSubscriptions: [
      ...currentSubs,
      eventType
    ]
  });
  if (response.success) {
    writeSuccess(`\u2705 Webhook "${webhookName}" subscribed to ${eventType}`);
    return true;
  } else {
    console.error(`\u274C Failed to subscribe: ${response.error?.message || "Unknown error"}`);
    return false;
  }
}
