async function enrichJobsWithServerStatus(context, configJobs) {
  const jobApi = new JobApi(BASE_URLS.API, context.apiKey, context.agentId);
  const serverResponse = await jobApi.getJobs();
  if (!serverResponse.success || !serverResponse.data?.jobs) return configJobs;
  const serverMap = new Map(serverResponse.data.jobs.map((j) => [
    j.id,
    j
  ]));
  return configJobs.map((job) => {
    const serverJob = serverMap.get(job.jobId);
    return serverJob ? {
      ...job,
      status: serverJob.status,
      active: serverJob.active
    } : job;
  });
}
