async function manageProductionJobs(context, config) {
  let continueManaging = true;
  while (continueManaging) {
    console.log("\n" + "=".repeat(60));
    console.log("\u{1F680} Production Jobs");
    console.log("=".repeat(60) + "\n");
    const actionAnswer = await safePrompt([
      {
        type: "list",
        name: "action",
        message: "What would you like to do?",
        choices: [
          {
            name: "\u{1F441}\uFE0F  View deployed jobs",
            value: "view"
          },
          {
            name: "\u{1F4DC} View job versions",
            value: "versions"
          },
          {
            name: "\u{1F680} Deploy a version",
            value: "deploy"
          },
          {
            name: "\u2705 Activate a job",
            value: "activate"
          },
          {
            name: "\u{1F6AB} Deactivate a job",
            value: "deactivate"
          },
          {
            name: "\u26A1 Trigger job now",
            value: "trigger"
          },
          {
            name: "\u{1F4CA} View execution history",
            value: "history"
          },
          {
            name: "\u{1F5D1}\uFE0F  Delete a job",
            value: "delete"
          },
          {
            name: "\u274C Exit",
            value: "exit"
          }
        ]
      }
    ]);
    if (!actionAnswer) return;
    const { action } = actionAnswer;
    switch (action) {
      case "view":
        await viewDeployedJobsInteractive(context, config);
        break;
      case "versions":
        await viewJobVersionsInteractive(context, config);
        break;
      case "deploy":
        await deployJobVersionInteractive(context, config);
        break;
      case "activate":
        await activateJobInteractive(context, config);
        break;
      case "deactivate":
        await deactivateJobInteractive(context, config);
        break;
      case "trigger":
        await triggerJobInteractive(context, config);
        break;
      case "history":
        await viewExecutionHistoryInteractive(context, config);
        break;
      case "delete":
        await deleteJobInteractive(context, config);
        break;
      case "exit":
        continueManaging = false;
        console.log("\n\u{1F44B} Goodbye!\n");
        break;
    }
  }
}
