async function mcpCommand(action, serverNamePositional, cmdObj) {
  return withErrorHandling(async () => {
    const options = {
      serverName: cmdObj?.serverName || serverNamePositional || null
    };
    const { agentId, apiKey } = await initializeCommand();
    const developerApi = new DeveloperApi(BASE_URLS.API, apiKey, agentId);
    const context = {
      agentId,
      apiKey,
      developerApi
    };
    if (action) {
      await executeNonInteractive10(context, action, options);
    } else {
      await interactiveMCPManagement(context);
    }
    trackEvent("cli_mcp_action", {
      action: action || "interactive",
      server_name: options.serverName || null,
      non_interactive: !!action
    });
  }, "mcp");
}
