async function executeNonInteractive10(context, action, options) {
  const resolvedAction = validateOrSuggest("mcp.action", action);
  writeProgress("\u{1F504} Loading MCP servers...");
  const servers = await fetchServersCore(context);
  if (!servers) throw new Error("Operation failed");
  if (resolvedAction === "list") {
    displayServersCore(servers);
    return;
  }
  if (!options.serverName) {
    console.error(`\u274C --server-name is required for action "${resolvedAction}"`);
    console.log(`
Usage: lua mcp ${resolvedAction} --server-name <name>`);
    if (servers.length > 0) {
      console.log("\nAvailable servers:");
      servers.forEach((s) => console.log(`  - ${s.name} ${s.active ? "(active)" : "(inactive)"}`));
    }
    throw new Error("Operation failed");
  }
  const selectedServer = findServer(servers, options.serverName);
  if (!selectedServer) {
    console.error(`\u274C MCP server "${options.serverName}" not found`);
    if (servers.length > 0) {
      console.log("\nAvailable servers:");
      servers.forEach((s) => console.log(`  - ${s.name}`));
    }
    throw new Error("Operation failed");
  }
  switch (resolvedAction) {
    case "activate": {
      const success2 = await activateServerCore(context, selectedServer);
      if (!success2) throw new Error("Operation failed");
      break;
    }
    case "deactivate": {
      const success2 = await deactivateServerCore(context, selectedServer);
      if (!success2) throw new Error("Operation failed");
      break;
    }
    case "delete": {
      const success2 = await deleteServerCore(context, selectedServer);
      if (!success2) throw new Error("Operation failed");
      break;
    }
  }
}
